  function connect(action){stopNetwork();online=true;intent=action;mode='connecting';retry=time;reconnectUntil=time+8;message('Connecting to '+address);}
  function collectEvents(){if(lastFrame===state.frame)return;for(const e of state.events||[])if(state.visible[team]?.[S.index(e.x,e.z)])pendingFx.push(e);if(pendingFx.length>48)pendingFx.splice(0,pendingFx.length-48);lastFrame=state.frame;}
  function receive(){
    for(const e of engine.network.poll()){
      if(e.type==='connected'){connected=true;lastReceive=time;engine.network.send({type:'hello',protocol:S.PROTOCOL,name:'Commander'});}
      if(e.type==='closed'){connected=false;if(online&&token){mode='reconnecting';intent='resume';retry=time+.5;reconnectUntil=time+12;message('Connection lost. Reconnecting...');}else if(online){online=false;mode='network';message('Connection failed. Start server.mjs and check the address.');}}
      if(e.type!=='message')continue;const m=e.data;lastReceive=time;
      if(m.type==='welcome'){
        if(intent==='create')engine.network.send({type:'create',mode:editMap.mode==='moba'?'moba':'skirmish',map:editMap.mode==='td'?S.defaultMap():editMap,faction,heroClass});
        if(intent==='browse'){engine.network.send({type:'list'});mode='rooms';}
        if(intent==='resume')engine.network.send({type:'resume',code,token});
      }
      if(m.type==='joined'){
        missileView.reset();unitView.reset();unitPositions.clear();for(const id of Object.keys(previous))delete previous[id];
        const resumed=intent==='resume'&&!!m.state;team=m.team;token=m.token;code=m.code;seq=0;if(m.state){state=m.state;collectEvents();mode=state.winner===null?'playing':'finished';}else mode='lobby';
        if(resumed){selected=selected.filter(id=>state.units.some(u=>u.id===id&&S.canControl(state,team,u)&&u.hp>0&&!u.inside));message('Connection restored.');}
        else{selected=[];camera=[...(m.state?.map.spawns[team]||[team?23:-23,team?-23:23])];zoom=18;notice='';noticeUntil=0;}
      }
      if(m.type==='room'){room=m;if(m.phase==='playing'&&state?.frame>0)mode='playing';}
      if(m.type==='rooms'){rooms=m.rooms;roomIndex=S.clamp(roomIndex,0,Math.max(0,rooms.length-1));}
      if(m.type==='state'){state=m.state;collectEvents();netStates++;mode=state.winner===null?'playing':'finished';if(!selected.length)selected=state.units.filter(u=>u.team===team&&u.kind==='hero').map(u=>u.id);}
      if(m.type==='error'){message(m.message);if(intent==='resume'&&m.message.includes('expired')){stopNetwork();mode='network';}}
    }
    if(online&&!connected&&time>=retry){if(time>reconnectUntil){stopNetwork();mode='network';message('Connection timed out');}else {engine.network.connect(address);retry=time+3;}}
    if(connected&&Math.floor(time)%3===0&&Math.floor(time)!==receive.lastPing){receive.lastPing=Math.floor(time);engine.network.send({type:'ping',nonce:time});}
    if(connected&&time-lastReceive>8)engine.network.close();
  }
  function inBattlefield(p){const r=authored['HUD Skyline'].RectTransform;return p.y<(mode==='editor'?160:r.anchored_position[1]-r.size_delta[1]/2);}
  function screenPointer(input){const [w,h]=input.viewport?.every(v=>v>1)?input.viewport:[1280,720],scale=['playing','editor','finished','reconnecting'].includes(mode)?Math.sqrt(w/1280*h/720):w/1280;return {x:(input.pointer[0]-w/2)/scale,y:(input.pointer[1]-h/2)/scale};}
  function worldPointer(input){
    const [w,h]=input.viewport?.every(v=>v>1)?input.viewport:[1280,720],x=camera[0]+(input.pointer[0]/w*2-1)*zoom*w/h,base=camera[1]+(input.pointer[1]/h*2-1)*zoom/sin,map=mode==='editor'?editMap:state.map;
    // Orthographic ray marches down from above the highest authored terrain, finding the front surface.
    let y=9.01,z=base+y*Math.cos(pitch)/sin;
    for(;y>=-1.05;y-=.04){z=base+y*Math.cos(pitch)/sin;if(y<=S.pickHeight(map,x,z)){let lo=y,hi=y+.04;for(let k=0;k<8;k++){const mid=(lo+hi)/2;if(mid<=S.pickHeight(map,x,base+mid*Math.cos(pitch)/sin))lo=mid;else hi=mid;}z=base+hi*Math.cos(pitch)/sin;break;}}
    if(y< -1.05)z=base;return {x:S.clamp(x,-30,30),z:S.clamp(z,-30,30)};
  }
  function screenWorld(u,input){const position=S.types[u.kind]&&unitPositions.get(u.id)||u;const [w,h]=input.viewport?.every(v=>v>1)?input.viewport:[1280,720],scale=Math.sqrt(w/1280*h/720);return {x:(position.x-camera[0])/zoom*h/2/scale,y:((position.z-camera[1])*sin-(u.y??position.y??S.unitHeight(state,u))*Math.cos(pitch))/zoom*h/2/scale};}
